// Operational preview profiles. Internal source documents remain in the private skill.
export const VERSION='2026-10-15.2';
export const PROFILES=[
 {id:'demo',label:'Demo — no regional profile',auto:100,turbo:true,bonus:true},
 {id:'gb-ukgc',label:'United Kingdom (UKGC)',auto:0,turbo:false,bonus:false,cycle:5000,slotCycle:2500,reality:60,notes:'No autoplay, turbo or bonus purchases. UK slot caps depend on age.'},
 {id:'es',label:'Spain',auto:100,turbo:false,bonus:true,cycle:3000,currency:'EUR',languages:['es'],reality:60,limits:true,notes:'Session spend limit enforced here. Time limits and reminders are handled by the operator.'},
 {id:'ca-qc',label:'Quebec',auto:50,turbo:false,bonus:true,cycle:3000,inactivity:30,minimumStake:true,notes:'Separate real/bonus balances and approved game liability remain operator responsibilities.'},
 {id:'pt',label:'Portugal',auto:50,turbo:true,bonus:false,cycle:3000,languages:['pt'],notes:'Operator autoplay cap: 50 for this demo. Bonus purchase/boost rules are under consultation; those features are unavailable here.'},
 {id:'us-pa',label:'Pennsylvania',auto:50,turbo:false,bonus:true,currency:'USD',reality:60,inactivity:15,notes:'Searchable rules; session reminders are handled by the operator. Turbo is unspecified, so this profile uses normal speed.'},
 {id:'ca-on',label:'Ontario',auto:0,turbo:false,bonus:false,cycle:2500,currency:'CAD',notes:'No autoplay, turbo or bonus purchases. Retain at least 10 games and 50 intermediate steps where applicable.'},
 {id:'us-nj',label:'New Jersey',auto:1000,authorization:true,turbo:false,bonus:true,inactivity:15,notes:'Autoplay needs Division authorization. This preview leaves it unavailable. Session reminders and inactivity timeouts are handled by the operator.'},
 {id:'us-mi',label:'Michigan',auto:50,authorization:true,turbo:false,bonus:true,inactivity:30,notes:'Autoplay needs Board authorization. This preview leaves it unavailable. Session reminders and inactivity timeouts are handled by the operator.'},
 {id:'mt',label:'Malta',auto:100,turbo:false,bonus:true,reality:30,notes:'Session reminders are handled by the operator. Normal speed follows the overview’s advice against turbo.'},
 {id:'it',label:'Italy',auto:0,turbo:false,bonus:true,languages:['it'],notes:'No autoplay. Turbo/bonus-purchase restrictions are unspecified; existing per-game bonus rules retained, normal speed used.'},
 {id:'br',label:'Brazil',auto:100,turbo:false,bonus:true,currency:'BRL',languages:['pt'],totalConfirmation:true,notes:'Autoplay displays and confirms its full commitment before starting. Turbo unspecified: normal speed. Existing game-specific bonus rules retained.'}
];
// UI defaults, separate from the source profiles’ mandatory-currency rules.
export const JURISDICTION_CURRENCIES={'gb-ukgc':'GBP',es:'EUR','ca-qc':'CAD',pt:'EUR','us-pa':'USD','ca-on':'CAD','us-nj':'USD','us-mi':'USD',mt:'EUR',it:'EUR',br:'BRL'};
export class RegionalSession{
 constructor(key,gameType){this.key=key;this.gameType=gameType;this.id='demo';this.bonusOverride=null;this.age='25+';this.spent=0;this.paid=0;this.started=Date.now();this.lastAction=Date.now();this.lastCheck=Date.now();this.nextAt=0;this.timeLimit=30;this.spendLimit=100;this.realityMinutes=30;this.paused=false;this.ended=false;this.host={};try{const s=JSON.parse(localStorage.getItem(key)||'null');if(s&&PROFILES.some(p=>p.id===s.id)){this.id=s.id;this.bonusOverride=typeof s.bonusOverride==='boolean'?s.bonusOverride:null;this.age=s.age||'25+';this.timeLimit=s.time||30;this.spendLimit=s.spend||100;this.realityMinutes=s.reality||30}}catch{}}
 get profile(){return PROFILES.find(p=>p.id===this.id)||PROFILES[0]}
 get defaultCurrency(){return JURISDICTION_CURRENCIES[this.id]||null}
 get bonusEnabled(){return this.bonusOverride??this.profile.bonus}
 get bonusOverridden(){return this.bonusEnabled!==this.profile.bonus}
 get bonusLabel(){return 'Show bonus features'+(this.bonusOverridden?' — Preview override':'')}
 setBonusEnabled(enabled){const state=this.host.read?.()||{};if(state.busy||state.replaying||state.bonusPending||state.winOpen)return 'Finish the round, dismiss its result and exit replay before changing bonus features.';this.host.stop?.();if(!enabled&&this.host.clearBonus?.()===false)return 'Finish the current bonus before turning bonus features off.';this.bonusOverride=!!enabled===this.profile.bonus?null:!!enabled;this.persist();this.emit();this.host.changed?.();return ''}
 persist(){try{localStorage.setItem(this.key,JSON.stringify({id:this.id,age:this.age,time:this.timeLimit,spend:this.spendLimit,reality:this.realityMinutes,bonusOverride:this.bonusOverride}))}catch{}}
 get autoMax(){return this.profile.authorization?0:this.profile.auto}
 get speeds(){return this.profile.turbo?[1,2,3]:[1]}
 get cycle(){return this.gameType==='slot'?(this.profile.slotCycle??this.profile.cycle??0):(this.profile.cycle??0)}
 get maxStake(){return this.id==='gb-ukgc'&&this.gameType==='slot'?(this.age==='18–24'?2:5):Infinity}
 get metadata(){return {jurisdiction:this.id,regionalVersion:VERSION,bonusOverride:this.bonusOverride}}
 configureHost(host){this.host=host}
 issues(){const s=this.host.read?.()||{};const p=this.profile;const out=[];if(p.currency&&s.currency!==p.currency)out.push(`Choose ${p.currency} in Language & currency.`);if(this.id==='gb-ukgc'&&this.gameType==='slot'&&s.currency!=='GBP')out.push('Choose GBP to apply the UK slot stake cap.');if(Number(s.stake)>this.maxStake)out.push(`Choose a stake no higher than ${this.maxStake} GBP.`);return out}
 canBet(cost){if(this.id==='demo')return '';if(this.paused)return 'Review the session reminder before continuing.';if(this.ended)return 'Session limit reached. Start a new demo session in Jurisdiction settings.';const issue=this.issues()[0];if(issue)return issue;if(Date.now()<this.nextAt)return 'Please wait for the minimum round duration.';if(this.profile.limits&&(this.spent+cost>this.spendLimit))return 'Session spend limit reached.';return ''}
 accept(cost){this.lastAction=Date.now();this.nextAt=Date.now()+this.cycle;this.spent+=cost;return {...this.metadata}}
 settle(paid){this.paid+=paid;this.emit()}
 action(){this.lastAction=Date.now()}
 autoAllowed(rounds){return Number.isInteger(rounds)&&rounds>0&&rounds<=this.autoMax}
 async confirmAuto(rounds,stake){if(!this.autoAllowed(rounds))return false;if(!this.profile.totalConfirmation)return true;return confirm(`Start ${rounds} rounds at ${this.host.money?.(stake)||stake} each? Total commitment: ${this.host.money?.(rounds*stake)||rounds*stake}. You can stop after an accepted round.`)}
 apply(id,age,time,spend,reality){const state=this.host.read?.()||{};if(state.busy||state.replaying||state.bonusPending||state.winOpen)return 'Finish the round and exit replay/awarded bonus rounds first.';if(!PROFILES.some(p=>p.id===id))return 'Unknown jurisdiction.';if(!Number.isFinite(spend)||spend<=0)return 'Use a positive session spend limit.';this.host.stop?.();const currency=JURISDICTION_CURRENCIES[id];if(currency){const error=this.host.applyCurrency?.(currency);if(error)return error}this.bonusOverride=null;this.id=id;this.age=age;this.timeLimit=time;this.spendLimit=spend;this.realityMinutes=reality;this.started=this.lastCheck=this.lastAction=Date.now();this.spent=this.paid=0;this.nextAt=0;this.paused=this.ended=this.warned=false;this.host.resetFeatures?.(this);this.persist();this.emit();return ''}
 emit(){window.dispatchEvent(new CustomEvent('regional-change'))}
 tick(){if(this.id==='demo'||this.dialog?.open)return;let message='';if(this.profile.limits&&this.spent>=this.spendLimit){this.ended=true;message='Your session spend limit has been reached.'}else if(this.profile.limits&&!this.warned&&this.spent>=this.spendLimit*.95){this.warned=true;message='Your session is approaching its spend limit (5% remaining).'}if(message&&!this.paused){this.paused=true;this.host.stop?.();this.remind(message);this.emit()}}
 remind(message){const d=document.createElement('dialog');d.className='regional-dialog';d.setAttribute('aria-label','Session reminder');const title=document.createElement('h2');title.textContent=message;const p=document.createElement('p');p.textContent=`Elapsed: ${Math.floor((Date.now()-this.started)/60000)} minutes. Wagered: ${this.host.money?.(this.spent)||this.spent}. Returned: ${this.host.money?.(this.paid)||this.paid}.`;const button=document.createElement('button');button.textContent=this.ended?'Close session':'Continue demo';button.onclick=()=>{d.close();d.remove();this.paused=false;this.lastCheck=this.lastAction=Date.now();this.emit()};d.append(title,p,button);d.addEventListener('cancel',e=>e.preventDefault());document.body.append(d);d.showModal()}
 open(){if(!this.dialog){const d=document.createElement('dialog');d.className='regional-dialog';d.setAttribute('aria-label','Jurisdiction');d.innerHTML=`<form method="dialog"><h2>Jurisdiction</h2><label>Regional profile<select name="region">${PROFILES.map(p=>`<option value="${p.id}">${p.label}</option>`).join('')}</select></label><label data-age>UK slot age band<select name="age"><option>25+</option><option>18–24</option></select></label><label data-limits>Session spend limit (selected currency)<input name="spend" type="number" min="0.01" step="0.01" value="100"></label><p data-summary></p><p>Session time limits, timed reminders and inactivity timeouts are handled by the hosting operator.</p><p>Regional demo settings. Operator authorization, certification, account services and game maths remain separate. Applying stops autoplay and starts a new regional demo session. A currency change resets demo funds, stakes, history and active bonuses; it does not convert funds.</p><p role="status" data-error></p><div class="regional-actions"><button value="cancel">Cancel</button><button type="button" data-apply>Apply profile</button></div></form>`;document.body.append(d);this.dialog=d;const select=d.querySelector('[name=region]');const update=()=>{const p=PROFILES.find(p=>p.id===select.value);d.querySelector('[data-summary]').textContent=(p.notes||'Original game behaviour with normal, 2× and 3× speed.')+' '+(JURISDICTION_CURRENCIES[p.id]?'Currency: '+JURISDICTION_CURRENCIES[p.id]+'.':'Keeps your selected currency.');d.querySelector('[data-age]').hidden=!(p.id==='gb-ukgc'&&this.gameType==='slot');for(const el of d.querySelectorAll('[data-limits]'))el.hidden=!p.limits};select.onchange=update;d.querySelector('[data-apply]').onclick=()=>{const f=d.querySelector('form').elements;const error=this.apply(f.region.value,f.age.value,this.timeLimit,Number(f.spend.value),this.realityMinutes);d.querySelector('[data-error]').textContent=error;if(!error){d.close();this.host.changed?.()}};d.addEventListener('close',()=>this.host.panel?.(false));this.updateDialog=update}this.host.stop?.();this.host.panel?.(true);this.dialog.querySelector('[name=region]').value=this.id;this.dialog.querySelector('[name=age]').value=this.age;for(const [name,value] of [['spend',this.spendLimit]])this.dialog.querySelector('[name='+name+']').value=value;this.dialog.querySelector('[data-error]').textContent='';this.updateDialog();this.dialog.showModal()}
 mount(){if(document.querySelector('#regional-styles'))return;const s=document.createElement('style');s.id='regional-styles';s.textContent=`.regional-dialog{box-sizing:border-box;width:min(420px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;padding:24px;color:var(--text-color-default,#fff);background:var(--surface-background-primary,#181818);border:1px solid var(--stroke-color-default,#888);border-radius:8px;font:14px/1.5 Inter,sans-serif}.regional-dialog::backdrop{background:#0009}.regional-dialog h2{margin:0 0 16px}.regional-dialog label{display:flex;flex-direction:column;gap:6px;margin:12px 0}.regional-dialog [hidden]{display:none}.regional-dialog select,.regional-dialog input{box-sizing:border-box;width:100%;min-height:40px;padding:8px;background:#222;color:white;border:1px solid #888;border-radius:4px;font:inherit}.regional-dialog p{font-size:12px}.regional-dialog button{appearance:none;box-sizing:border-box;padding:10px 16px;min-height:44px;white-space:normal;font:inherit;font-weight:var(--font-weight-semibold,600);cursor:pointer;border:var(--stroke-weight-100,1px) solid var(--stroke-color-default,#888);border-radius:var(--border-radius-40,4px);background:var(--button-background-highlight,#fff);color:var(--button-text-color-primary,var(--button-text-color,#000))}.regional-dialog button[value="cancel"]{background:var(--button-background-default,#222);color:var(--button-text-color-secondary,var(--text-color-default,#fff))}.regional-dialog button:hover{background:var(--button-background-primary-hover,#bcbcbc);color:var(--button-text-color-primary,var(--button-text-color,#000))}.regional-dialog button:active{background:var(--button-background-primary-pressed,#ccc);color:var(--button-text-color-primary,var(--button-text-color,#000))}.regional-dialog button:focus-visible{outline:2px solid var(--stroke-color-focus,#b69cff);outline-offset:3px}.regional-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:12px}`;document.head.append(s);this.timer=setInterval(()=>this.tick(),1000);document.addEventListener('pointerdown',()=>this.action());document.addEventListener('keydown',()=>this.action())}
}
